import{_ as a,o as t,c as l,a4 as r}from"./chunks/framework.9tZL7ZIQ.js";const p=JSON.parse('{"title":"谢尔顿·蔡尔德","description":"","frontmatter":{"title":"谢尔顿·蔡尔德","date":"2026-04-13T00:00:00.000Z"},"headers":[],"relativePath":"04_people/谢尔顿·蔡尔德.md","filePath":"04_people/谢尔顿·蔡尔德.md"}'),o={name:"04_people/谢尔顿·蔡尔德.md"};function i(n,e,s,h,d,_){return t(),l("div",null,[...e[0]||(e[0]=[r('<h1 id="谢尔顿·蔡尔德-sheldon-child" tabindex="-1">谢尔顿·蔡尔德（Sheldon Child） <a class="header-anchor" href="#谢尔顿·蔡尔德-sheldon-child" aria-label="Permalink to &quot;谢尔顿·蔡尔德（Sheldon Child）&quot;">​</a></h1><ul><li><strong>角色职位</strong>：R.C.威利家居（R.C. Willey）管理层</li><li><strong>与巴菲特关系</strong>：威利家居核心管理层成员，家族与企业深度绑定</li></ul><h2 id="主要事迹" tabindex="-1">主要事迹 <a class="header-anchor" href="#主要事迹" aria-label="Permalink to &quot;主要事迹&quot;">​</a></h2><p>谢尔顿·蔡尔德是R.C.威利家居管理团队的重要成员。R.C.威利家居是美国西部领先的家居零售商，以仓储式仓储销售模式在犹他州及周边各州建立起了强大的市场地位。谢尔顿·蔡尔德在威利家居的管理工作中发挥了关键作用，负责公司的日常运营与战略执行。威利家居自1954年创立以来，在蔡尔德家族及专业管理团队的带领下，实现了持续增长。伯克希尔·哈撒韦于1995年收购威利家居后，谢尔顿·蔡尔德继续留在管理层，确保公司运营的平稳过渡与延续。他的领导风格注重客户价值与运营效率，与巴菲特所推崇的商业理念高度契合。</p><h2 id="关键年份事件" tabindex="-1">关键年份事件 <a class="header-anchor" href="#关键年份事件" aria-label="Permalink to &quot;关键年份事件&quot;">​</a></h2><ul><li><strong>1995年</strong>：伯克希尔收购威利家居，谢尔顿·蔡尔德作为管理团队核心成员参与过渡</li><li><strong>1995年后</strong>：继续在威利家居管理层任职，支持公司在新东家下的整合与扩张</li></ul><hr><p><em>本档案基于公开信息整理，伯克希尔知识库</em></p><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该人物在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/search?q=谢尔顿·蔡尔德在1995年股东信中的原话">1995年：完整翻译|/01_letters/1995年/翻译</a></li></ul>',11)])])}const u=a(o,[["render",i]]);export{p as __pageData,u as default};
